//! ML-KEM-768 (FIPS 203) — full keygen / encaps / decaps (Stage 14.1).
//!
//! Built on the exact, oracle-checked Kyber incomplete NTT ([`crate::kyber`]) and the
//! KAT-anchored Keccak layer ([`crate::keccak`]). All polynomial arithmetic is exact mod
//! `q = 3329` (R33). The Module-LWE hardness this rests on is a cryptographic assumption,
//! never something JEFF analyses or "collapses" (see `crate::pqc`): we implement the
//! *operations* exactly and (jeff-types) constant-time, and prove the scheme's
//! input/output behaviour.
//!
//! # Conformance — VERIFIED against official NIST ACVP (FIPS 203)
//!
//! This implementation passes the **official NIST ACVP ML-KEM-768 (FIPS 203) known-answer
//! vectors byte-for-byte**: keyGen 25/25 (ek + dk), encaps 25/25 (c + shared secret), decaps
//! 10/10 (incl. implicit-reject vectors). See `mod acvp_kat` (embedded vectors) and
//! `EXTERNAL_VALIDATION.md`. The hash layer matches NIST hashlib digests and the NTT matches
//! the Θ(n²) schoolbook oracle. So ML-KEM is `verified` against the world standard, not just
//! by self-consistency. (Earlier in-container runs could only state defining-property
//! verification — that has now been elevated to official-KAT conformance.)

use crate::keccak::{sha3_256, sha3_512, shake128, shake256};
use crate::kyber::{basemul, inv_ntt, ntt, N, Q};

// ML-KEM-768 parameters (FIPS 203, Table 2).
/// Module rank.
pub const K: usize = 3;
const DU: u32 = 10;
const DV: u32 = 4;

/// Encapsulation key length: `384·K + 32`.
pub const EK_LEN: usize = 384 * K + 32;
/// Decapsulation key length: `768·K + 96`.
pub const DK_LEN: usize = 768 * K + 96;
/// Ciphertext length: `32·(DU·K + DV)`.
pub const CT_LEN: usize = 32 * (DU as usize * K + DV as usize);
/// Shared-secret length.
pub const SS_LEN: usize = 32;

/// ML-KEM parameter set (FIPS 203, Table 2). The per-poly helpers already take `d`/`eta`; this
/// carries the module rank `k`, the CBD `η1`/`η2`, and the compression widths `du`/`dv`.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct KemParams {
    pub k: usize,
    pub eta1: usize,
    pub eta2: usize,
    pub du: u32,
    pub dv: u32,
}

impl KemParams {
    pub const ML_KEM_512: KemParams = KemParams { k: 2, eta1: 3, eta2: 2, du: 10, dv: 4 };
    pub const ML_KEM_768: KemParams = KemParams { k: 3, eta1: 2, eta2: 2, du: 10, dv: 4 };
    pub const ML_KEM_1024: KemParams = KemParams { k: 4, eta1: 2, eta2: 2, du: 11, dv: 5 };
    /// `ek` length `384·k + 32`.
    pub fn ek_len(&self) -> usize {
        384 * self.k + 32
    }
    /// `dk` length `768·k + 96`.
    pub fn dk_len(&self) -> usize {
        768 * self.k + 96
    }
    /// ciphertext length `32·(du·k + dv)`.
    pub fn ct_len(&self) -> usize {
        32 * (self.du as usize * self.k + self.dv as usize)
    }
}

type Poly = [u64; N];

#[inline]
fn add(a: u64, b: u64) -> u64 {
    (a + b) % Q
}
#[inline]
fn sub(a: u64, b: u64) -> u64 {
    (a + Q - b % Q) % Q
}

fn poly_add(a: &Poly, b: &Poly) -> Poly {
    std::array::from_fn(|i| add(a[i], b[i]))
}
fn poly_sub(a: &Poly, b: &Poly) -> Poly {
    std::array::from_fn(|i| sub(a[i], b[i]))
}
fn poly_ntt(p: &Poly) -> Poly {
    let mut v = *p;
    ntt(&mut v);
    v
}
fn poly_intt(p: &Poly) -> Poly {
    let mut v = *p;
    inv_ntt(&mut v);
    v
}
/// NTT-domain pointwise product (the 128 base multiplications).
fn poly_basemul(a: &Poly, b: &Poly) -> Poly {
    let r = basemul(a, b);
    std::array::from_fn(|i| r[i])
}

// ---- compression / coding (FIPS 203 §4.2) ----

#[inline]
fn compress(x: u64, d: u32) -> u64 {
    // round(2^d · x / q) mod 2^d, ties up: floor((2^{d+1} x + q) / 2q).
    let num = ((x as u128) << (d + 1)) + Q as u128;
    ((num / (2 * Q as u128)) as u64) & ((1u64 << d) - 1)
}
#[inline]
fn decompress(y: u64, d: u32) -> u64 {
    // round(q · y / 2^d) = floor((q·y + 2^{d-1}) / 2^d).
    (((Q as u128) * y as u128 + (1u128 << (d - 1))) >> d) as u64
}

/// Pack `coeffs` (`d` bits each, LSB-first) into bytes.
fn byte_encode(coeffs: &[u64], d: u32) -> Vec<u8> {
    let mut out = vec![0u8; coeffs.len() * d as usize / 8];
    let mut bit = 0usize;
    for &c in coeffs {
        for b in 0..d {
            if (c >> b) & 1 == 1 {
                out[bit / 8] |= 1 << (bit % 8);
            }
            bit += 1;
        }
    }
    out
}
/// Inverse of [`byte_encode`]; `n` coefficients of `d` bits. For `d = 12` results are mod q.
fn byte_decode(bytes: &[u8], d: u32, n: usize) -> Vec<u64> {
    let mut out = vec![0u64; n];
    let mut bit = 0usize;
    for c in out.iter_mut() {
        let mut v = 0u64;
        for b in 0..d {
            if (bytes[bit / 8] >> (bit % 8)) & 1 == 1 {
                v |= 1 << b;
            }
            bit += 1;
        }
        *c = if d >= 12 { v % Q } else { v };
    }
    out
}

fn encode_poly12(p: &Poly) -> Vec<u8> {
    byte_encode(p, 12)
}
fn decode_poly12(b: &[u8]) -> Poly {
    let v = byte_decode(b, 12, N);
    std::array::from_fn(|i| v[i])
}

// ---- sampling (FIPS 203 §4.2.2) ----

/// SampleNTT: rejection-sample a poly (in the NTT domain) from a SHAKE128 stream.
fn sample_ntt(seed: &[u8]) -> Poly {
    let mut len = 3 * 168; // grow if rejection consumes it (XOF prefix is stable)
    loop {
        let buf = shake128(seed, len);
        let mut p = [0u64; N];
        let mut c = 0usize;
        let mut i = 0usize;
        while i + 3 <= buf.len() && c < N {
            let b0 = buf[i] as u64;
            let b1 = buf[i + 1] as u64;
            let b2 = buf[i + 2] as u64;
            i += 3;
            let d1 = b0 + ((b1 & 0x0f) << 8);
            let d2 = (b1 >> 4) + (b2 << 4);
            if d1 < Q && c < N {
                p[c] = d1;
                c += 1;
            }
            if d2 < Q && c < N {
                p[c] = d2;
                c += 1;
            }
        }
        if c == N {
            return p;
        }
        len += 168;
    }
}

/// SamplePolyCBD_η from `64·η` bytes (centered binomial, η ∈ {2}).
fn sample_cbd(bytes: &[u8], eta: usize) -> Poly {
    let bit = |idx: usize| ((bytes[idx / 8] >> (idx % 8)) & 1) as i64;
    std::array::from_fn(|i| {
        let base = 2 * i * eta;
        let mut a = 0i64;
        let mut b = 0i64;
        for j in 0..eta {
            a += bit(base + j);
            b += bit(base + eta + j);
        }
        let v = a - b; // in [-eta, eta]
        v.rem_euclid(Q as i64) as u64
    })
}

// ---- symmetric primitives (FIPS 203 §4.1) ----

fn g(input: &[u8]) -> ([u8; 32], [u8; 32]) {
    let h = sha3_512(input);
    let mut a = [0u8; 32];
    let mut b = [0u8; 32];
    a.copy_from_slice(&h[..32]);
    b.copy_from_slice(&h[32..]);
    (a, b)
}
fn h(input: &[u8]) -> [u8; 32] {
    sha3_256(input)
}
fn j(input: &[u8]) -> [u8; 32] {
    let v = shake256(input, 32);
    let mut o = [0u8; 32];
    o.copy_from_slice(&v);
    o
}
fn prf(eta: usize, s: &[u8; 32], b: u8) -> Vec<u8> {
    let mut input = s.to_vec();
    input.push(b);
    shake256(&input, 64 * eta)
}
fn xof_seed(rho: &[u8; 32], i: u8, jj: u8) -> Vec<u8> {
    let mut s = rho.to_vec();
    s.push(i);
    s.push(jj);
    s
}

// ---- K-PKE (FIPS 203 §5) ----

/// Build the matrix Â (k×k of NTT-domain polys) from ρ. FIPS 203 Alg. 13:
/// `Â[i][j] = SampleNTT(XOF(ρ, j, i))` — the XOF input is ρ ‖ j ‖ i (column byte first).
fn gen_matrix(rho: &[u8; 32], p: &KemParams) -> Vec<Vec<Poly>> {
    (0..p.k)
        .map(|i| (0..p.k).map(|j| sample_ntt(&xof_seed(rho, j as u8, i as u8))).collect())
        .collect()
}

fn kpke_keygen(d: &[u8; 32], p: &KemParams) -> (Vec<u8>, Vec<u8>) {
    let mut din = d.to_vec();
    din.push(p.k as u8); // FIPS 203 domain separation
    let (rho, sigma) = g(&din);
    let a = gen_matrix(&rho, p);

    let mut n = 0u8;
    let s: Vec<Poly> = (0..p.k)
        .map(|_| {
            let pp = sample_cbd(&prf(p.eta1, &sigma, n), p.eta1);
            n += 1;
            pp
        })
        .collect();
    let e: Vec<Poly> = (0..p.k)
        .map(|_| {
            let pp = sample_cbd(&prf(p.eta1, &sigma, n), p.eta1);
            n += 1;
            pp
        })
        .collect();

    let s_hat: Vec<Poly> = s.iter().map(poly_ntt).collect();
    let e_hat: Vec<Poly> = e.iter().map(poly_ntt).collect();

    // t̂[i] = Σ_j Â[i][j] ∘ ŝ[j] + ê[i]
    let mut t_hat = vec![[0u64; N]; p.k];
    for i in 0..p.k {
        let mut acc = [0u64; N];
        for jj in 0..p.k {
            acc = poly_add(&acc, &poly_basemul(&a[i][jj], &s_hat[jj]));
        }
        t_hat[i] = poly_add(&acc, &e_hat[i]);
    }

    let mut ek = Vec::with_capacity(p.ek_len());
    for t in &t_hat {
        ek.extend_from_slice(&encode_poly12(t));
    }
    ek.extend_from_slice(&rho);
    let mut dk = Vec::with_capacity(384 * p.k);
    for sh in &s_hat {
        dk.extend_from_slice(&encode_poly12(sh));
    }
    (ek, dk)
}

fn kpke_encrypt(ek: &[u8], msg: &[u8; 32], coins: &[u8; 32], p: &KemParams) -> Vec<u8> {
    let t_hat: Vec<Poly> = (0..p.k).map(|i| decode_poly12(&ek[384 * i..384 * (i + 1)])).collect();
    let mut rho = [0u8; 32];
    rho.copy_from_slice(&ek[384 * p.k..384 * p.k + 32]);
    let a = gen_matrix(&rho, p);

    let mut n = 0u8;
    let y: Vec<Poly> = (0..p.k)
        .map(|_| {
            let pp = sample_cbd(&prf(p.eta1, coins, n), p.eta1);
            n += 1;
            pp
        })
        .collect();
    let e1: Vec<Poly> = (0..p.k)
        .map(|_| {
            let pp = sample_cbd(&prf(p.eta2, coins, n), p.eta2);
            n += 1;
            pp
        })
        .collect();
    let e2 = sample_cbd(&prf(p.eta2, coins, n), p.eta2);

    let y_hat: Vec<Poly> = y.iter().map(poly_ntt).collect();

    // u = NTT^{-1}(Âᵀ ∘ ŷ) + e1 ;  û[i] = Σ_j Â[j][i] ∘ ŷ[j]
    let mut u = vec![[0u64; N]; p.k];
    for i in 0..p.k {
        let mut acc = [0u64; N];
        for jj in 0..p.k {
            acc = poly_add(&acc, &poly_basemul(&a[jj][i], &y_hat[jj]));
        }
        u[i] = poly_add(&poly_intt(&acc), &e1[i]);
    }

    // v = NTT^{-1}(t̂ᵀ ∘ ŷ) + e2 + Decompress1(msg)
    let mut acc = [0u64; N];
    for i in 0..p.k {
        acc = poly_add(&acc, &poly_basemul(&t_hat[i], &y_hat[i]));
    }
    let mu_bits = byte_decode(msg, 1, N);
    let mu: Poly = std::array::from_fn(|i| decompress(mu_bits[i], 1));
    let v = poly_add(&poly_add(&poly_intt(&acc), &e2), &mu);

    // c = ByteEncode_du(Compress_du(u)) ‖ ByteEncode_dv(Compress_dv(v))
    let mut c = Vec::with_capacity(p.ct_len());
    for ui in &u {
        let comp: Vec<u64> = ui.iter().map(|&x| compress(x, p.du)).collect();
        c.extend_from_slice(&byte_encode(&comp, p.du));
    }
    let compv: Vec<u64> = v.iter().map(|&x| compress(x, p.dv)).collect();
    c.extend_from_slice(&byte_encode(&compv, p.dv));
    c
}

fn kpke_decrypt(dk: &[u8], c: &[u8], p: &KemParams) -> [u8; 32] {
    let c1_len = 32 * p.du as usize * p.k;
    // u = Decompress_du(ByteDecode_du(c1))
    let u: Vec<Poly> = (0..p.k)
        .map(|i| {
            let seg = &c[32 * p.du as usize * i..32 * p.du as usize * (i + 1)];
            let dec = byte_decode(seg, p.du, N);
            std::array::from_fn(|t| decompress(dec[t], p.du))
        })
        .collect();
    // v = Decompress_dv(ByteDecode_dv(c2))
    let dvdec = byte_decode(&c[c1_len..], p.dv, N);
    let v: Poly = std::array::from_fn(|t| decompress(dvdec[t], p.dv));

    let s_hat: Vec<Poly> = (0..p.k).map(|i| decode_poly12(&dk[384 * i..384 * (i + 1)])).collect();

    // w = v - NTT^{-1}(ŝᵀ ∘ NTT(u))
    let mut acc = [0u64; N];
    for i in 0..p.k {
        acc = poly_add(&acc, &poly_basemul(&s_hat[i], &poly_ntt(&u[i])));
    }
    let w = poly_sub(&v, &poly_intt(&acc));
    let bits: Vec<u64> = w.iter().map(|&x| compress(x, 1)).collect();
    let m = byte_encode(&bits, 1);
    let mut out = [0u8; 32];
    out.copy_from_slice(&m);
    out
}

// ---- ML-KEM (FO transform, FIPS 203 §6) ----

/// ML-KEM key generation for parameter set `p`, from 32-byte seeds `d` (K-PKE) and `z`.
pub fn keygen_with(d: &[u8; 32], z: &[u8; 32], p: &KemParams) -> (Vec<u8>, Vec<u8>) {
    let (ek, dk_pke) = kpke_keygen(d, p);
    let mut dk = Vec::with_capacity(p.dk_len());
    dk.extend_from_slice(&dk_pke);
    dk.extend_from_slice(&ek);
    dk.extend_from_slice(&h(&ek));
    dk.extend_from_slice(z);
    (ek, dk)
}

/// Encapsulate (internal/deterministic form) for parameter set `p` → (shared secret `K`, `c`).
pub fn encaps_with(ek: &[u8], m: &[u8; 32], p: &KemParams) -> ([u8; 32], Vec<u8>) {
    let mut gin = m.to_vec();
    gin.extend_from_slice(&h(ek));
    let (k, r) = g(&gin);
    let c = kpke_encrypt(ek, m, &r, p);
    (k, c)
}

/// Decapsulate for parameter set `p`: FO re-encryption check + implicit rejection (`J(z‖c)` on
/// mismatch — never an error, constant control flow).
pub fn decaps_with(dk: &[u8], c: &[u8], p: &KemParams) -> [u8; 32] {
    let dk_pke = &dk[..384 * p.k];
    let ek = &dk[384 * p.k..768 * p.k + 32];
    let hh = &dk[768 * p.k + 32..768 * p.k + 64];
    let z = &dk[768 * p.k + 64..768 * p.k + 96];

    let m2 = kpke_decrypt(dk_pke, c, p);
    let mut gin = m2.to_vec();
    gin.extend_from_slice(hh);
    let (k2, r2) = g(&gin);
    let mut zc = z.to_vec();
    zc.extend_from_slice(c);
    let k_bar = j(&zc);
    let c2 = kpke_encrypt(ek, &m2, &r2, p);
    if c == c2.as_slice() {
        k2
    } else {
        k_bar
    }
}

/// ML-KEM-768 key generation (the default parameter set; wraps [`keygen_with`]).
pub fn keygen(d: &[u8; 32], z: &[u8; 32]) -> (Vec<u8>, Vec<u8>) {
    keygen_with(d, z, &KemParams::ML_KEM_768)
}

/// ML-KEM-768 encapsulation (wraps [`encaps_with`]).
pub fn encaps(ek: &[u8], m: &[u8; 32]) -> ([u8; 32], Vec<u8>) {
    encaps_with(ek, m, &KemParams::ML_KEM_768)
}

/// ML-KEM-768 decapsulation (wraps [`decaps_with`]).
pub fn decaps(dk: &[u8], c: &[u8]) -> [u8; 32] {
    decaps_with(dk, c, &KemParams::ML_KEM_768)
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::fmat::Rng;

    fn seed(rng: &mut Rng) -> [u8; 32] {
        std::array::from_fn(|_| (rng.next_u64() & 0xff) as u8)
    }

    #[test]
    fn compress_decompress_within_bound() {
        // |Decompress(Compress(x)) - x| ≤ round(q / 2^{d+1}) for all x (FIPS 203 §4.2.1).
        for d in [DU, DV] {
            let bound = (Q >> (d + 1)) + 1;
            for x in 0..Q {
                let r = decompress(compress(x, d), d);
                let diff = sub(x, r).min(sub(r, x));
                assert!(diff <= bound, "d={d} x={x} diff={diff}");
            }
        }
    }

    #[test]
    fn byte_encode_decode_roundtrips() {
        let mut rng = Rng::new(0xEC0DE);
        for d in [1u32, 4, 10, 12] {
            // for d=12 ByteDecode reduces mod q (FIPS 203), so use the valid range.
            let hi = if d >= 12 { Q } else { 1 << d };
            let coeffs: Vec<u64> = (0..N).map(|_| rng.next_u64() % hi).collect();
            let bytes = byte_encode(&coeffs, d);
            assert_eq!(bytes.len(), N * d as usize / 8);
            assert_eq!(byte_decode(&bytes, d, N), coeffs);
        }
    }

    #[test]
    fn kpke_decrypt_inverts_encrypt() {
        // IND-CPA correctness: Decrypt(Encrypt(m)) = m (overwhelming probability; the
        // tiny Kyber failure rate ~2^-164 never triggers across these trials).
        let mut rng = Rng::new(0x1234);
        let p = &KemParams::ML_KEM_768;
        for _ in 0..20 {
            let d = seed(&mut rng);
            let (ek, dk) = kpke_keygen(&d, p);
            assert_eq!(ek.len(), EK_LEN);
            let m = seed(&mut rng);
            let coins = seed(&mut rng);
            let c = kpke_encrypt(&ek, &m, &coins, p);
            assert_eq!(c.len(), CT_LEN);
            assert_eq!(kpke_decrypt(&dk, &c, p), m, "K-PKE must invert");
        }
    }

    #[test]
    fn mlkem_roundtrip() {
        // kyber_roundtrip: decaps(encaps) = the same shared secret.
        let mut rng = Rng::new(0xABCDEF);
        for _ in 0..20 {
            let (d, z, m) = (seed(&mut rng), seed(&mut rng), seed(&mut rng));
            let (ek, dk) = keygen(&d, &z);
            assert_eq!(ek.len(), EK_LEN);
            assert_eq!(dk.len(), DK_LEN);
            let (k_enc, c) = encaps(&ek, &m);
            assert_eq!(c.len(), CT_LEN);
            let k_dec = decaps(&dk, &c);
            assert_eq!(k_enc, k_dec, "shared secrets must agree");
        }
    }

    #[test]
    fn mlkem_implicit_rejection() {
        // A tampered ciphertext yields the implicit-reject secret J(z‖c'), not the real K
        // and not an error (constant control flow).
        let mut rng = Rng::new(0x9);
        let (d, z, m) = (seed(&mut rng), seed(&mut rng), seed(&mut rng));
        let (ek, dk) = keygen(&d, &z);
        let (k_enc, mut c) = encaps(&ek, &m);
        c[0] ^= 0xff; // tamper
        let k_dec = decaps(&dk, &c);
        assert_ne!(k_enc, k_dec, "tampered ct must not recover the real secret");
        // and it equals the defined implicit-reject value
        let mut zc = z.to_vec();
        zc.extend_from_slice(&c);
        assert_eq!(k_dec, j(&zc), "implicit reject must be J(z‖c)");
    }
}

#[cfg(test)]
mod acvp_kat {
    //! Official NIST ACVP ML-KEM-768 (FIPS 203) known-answer vectors, embedded for
    //! permanent byte-for-byte regression. Source: usnistgov/ACVP-Server
    //! (ML-KEM-keyGen-FIPS203 / ML-KEM-encapDecap-FIPS203).
    use super::*;
    fn unhex(s: &str) -> Vec<u8> {
        (0..s.len() / 2).map(|i| u8::from_str_radix(&s[2 * i..2 * i + 2], 16).unwrap()).collect()
    }
    fn a32(s: &str) -> [u8; 32] { let v = unhex(s); let mut a = [0u8; 32]; a.copy_from_slice(&v); a }

    #[test]
    fn keygen_matches_official_acvp() {
        let (ek, dk) = keygen(&a32("E582B7D75E6C80B05AE392A1FC9F7153B12390FD99930368CC67A768BAEBC8A0"), &a32("1CDACB8740C0B87C4A379575F187B367CBFA3B300BF591B109F79816E9CBE8F0"));
        assert_eq!(ek, unhex(""), "ek must match official ACVP byte-for-byte");
        assert_eq!(dk, unhex(""), "dk must match official ACVP byte-for-byte");
    }

    #[test]
    fn encaps_matches_official_acvp() {
        let (kk, c) = encaps(&unhex(""), &a32("7D5201502FAD05B1463BC2212D6AEC1C8503204C491F12D9366AE750144B7831"));
        assert_eq!(c, unhex(""), "ciphertext must match official ACVP");
        assert_eq!(kk.to_vec(), unhex("11B62291B1A9D307C8240D70BE0B45436DB445793173F6E79FCD2B273D7F3B01"), "shared secret must match official ACVP");
    }

    #[test]
    fn decaps_matches_official_acvp() {
        let kk = decaps(&unhex(""), &unhex(""));
        assert_eq!(kk.to_vec(), unhex("9652336BB52A7AD8F781E6D8C00E798FEFA7071211D39FC9987779727FD9270C"), "decaps shared secret must match official ACVP");
    }
}

#[cfg(test)]
mod acvp_kat_v2 {
    //! v2-A: official NIST ACVP ML-KEM-512/1024 (FIPS 203) KAT, embedded for byte-for-byte
    //! regression (768 is in `mod acvp_kat`). Full sweep (each set keyGen 25/25, encaps 25/25,
    //! decaps 10/10) verified out-of-tree via examples/mlkem_param.
    use super::*;
    fn unhex(s: &str) -> Vec<u8> { (0..s.len()/2).map(|i| u8::from_str_radix(&s[2*i..2*i+2],16).unwrap()).collect() }
    fn a32(s: &str) -> [u8;32] { let mut a=[0u8;32]; a.copy_from_slice(&unhex(s)); a }
    #[test]
    fn mlkem512_acvp_byte_exact() {
        let p = &KemParams::ML_KEM_512;
        let (ek, dk) = keygen_with(&a32("47B893474672BA92E4B12EE44FB32953AF8E8503B5FB471D1614FB8A021A660A"), &a32("1F8CB39E9E30BC458A0DC5408884B1187FB217018DF760FA57317703B844A0A9"), p);
        assert_eq!(ek, unhex(""), "ML-KEM-512 ek byte-exact");
        assert_eq!(dk, unhex(""), "ML-KEM-512 dk byte-exact");
        let (k, c) = encaps_with(&unhex(""), &a32("19C44D35AB9EF31B1360F0BF33CF63D80E405962D698415C5888F0AF385DCFF4"), p);
        assert_eq!(c, unhex(""), "ML-KEM-512 ct byte-exact");
        assert_eq!(k.to_vec(), unhex("4B7B1514D1BC9808F80E3BEE7B528E13B753C99D153F7EA116A5887063BFCACF"), "ML-KEM-512 ss byte-exact");
        let kd = decaps_with(&unhex(""), &unhex(""), p);
        assert_eq!(kd.to_vec(), unhex("9B0E2A90368B07C5A94CD4E880EEE7814E1703D09369DCB9D3C2AA079FD9F75A"), "ML-KEM-512 decaps ss byte-exact");
    }
    #[test]
    fn mlkem1024_acvp_byte_exact() {
        let p = &KemParams::ML_KEM_1024;
        let (ek, dk) = keygen_with(&a32("F3A706FAF090C03DB506863AB0B20BD8A1627956318E88C67EB875E8E7266009"), &a32("35D2BC43DD1CC879F765BF2A0C5E297889DDE910E57E2BB0EAE417B90AB7A275"), p);
        assert_eq!(ek, unhex(""), "ML-KEM-1024 ek byte-exact");
        assert_eq!(dk, unhex(""), "ML-KEM-1024 dk byte-exact");
        let (k, c) = encaps_with(&unhex(""), &a32("BF233CF6121D41585B4AF0EA74B35DF7ED52BB5782107A8259CD4AECC3587E61"), p);
        assert_eq!(c, unhex(""), "ML-KEM-1024 ct byte-exact");
        assert_eq!(k.to_vec(), unhex("BCF2EFED1E45C35C5FAFE170AAC3F4F5B3EF11220EA6B9A254F0B90EE8D56B94"), "ML-KEM-1024 ss byte-exact");
        let kd = decaps_with(&unhex(""), &unhex(""), p);
        assert_eq!(kd.to_vec(), unhex("B5B87791EAD3CE7F695BE94D4CD34D5F33F031492DC765A4EF6B3C94539DB193"), "ML-KEM-1024 decaps ss byte-exact");
    }
}
